const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xfff4e6, 1.45);
keyLight.position.set(6, 12, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.camera.near = 0.5;
keyLight.shadow.camera.far = 50;
keyLight.shadow.bias = -0.001;

const fillLight = new THREE.DirectionalLight(0xcce0ff, 0.65);
fillLight.position.set(-8, 6, 6);

const rimLight = new THREE.SpotLight(0xaaddff, 0.85);
rimLight.position.set(-5, 8, -8);
rimLight.lookAt(0, 0, 0);
rimLight.penumbra = 0.5;

const ambientLight = new THREE.AmbientLight(0x8899aa, 0.35);

scene.add(keyLight, fillLight, rimLight, ambientLight);

const floorGeo = new THREE.CircleGeometry(12, 128);
const floorMat = new THREE.MeshStandardMaterial({ 
  color: 0xe8ecf2, 
  roughness: 0.85, 
  metalness: 0.05 
});
const floor = new THREE.Mesh(floorGeo, floorMat);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -1.2;
floor.receiveShadow = true;
scene.add(floor);

const dustParticles = [];
const dustGeo = new THREE.BufferGeometry();
const dustCount = 150;
const dustPositions = new Float32Array(dustCount * 3);
for(let i = 0; i < dustCount * 3; i += 3) {
  dustPositions[i] = (Math.random() - 0.5) * 20;
  dustPositions[i+1] = Math.random() * 8 - 1;
  dustPositions[i+2] = (Math.random() - 0.5) * 20;
}
dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPositions, 3));
const dustMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.03,
  transparent: true,
  opacity: 0.4,
  blending: THREE.AdditiveBlending
});
const dustSystem = new THREE.Points(dustGeo, dustMat);
scene.add(dustSystem);

function createLimb(width, length, material, name) {
  const group = new THREE.Group();
  const geo = new THREE.CapsuleGeometry(width, length, 8, 16);
  const mesh = new THREE.Mesh(geo, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  mesh.position.y = -length / 2;
  group.add(mesh);
  group.name = name;
  return { group, mesh };
}

function createJoint(size, material) {
  const geo = new THREE.SphereGeometry(size, 16, 16);
  const mesh = new THREE.Mesh(geo, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}

const skinMat = new THREE.MeshStandardMaterial({ 
  color: 0xffdbac, 
  roughness: 0.6, 
  metalness: 0.0 
});
const giMat = new THREE.MeshStandardMaterial({ 
  color: 0xf5f5f5, 
  roughness: 0.9, 
  metalness: 0.02 
});
const beltMat = new THREE.MeshStandardMaterial({ 
  color: 0x1a1a1a, 
  roughness: 0.95 
});
const hairMat = new THREE.MeshStandardMaterial({ 
  color: 0x0a0a0a, 
  roughness: 0.8 
});

const character = new THREE.Group();
scene.add(character);

const hips = new THREE.Group();
hips.position.y = 0.8;
character.add(hips);

const hipJoint = createJoint(0.18, giMat);
hips.add(hipJoint);

const torsoGroup = new THREE.Group();
hips.add(torsoGroup);

const spine = new THREE.Mesh(
  new THREE.CylinderGeometry(0.16, 0.18, 0.5, 16),
  giMat
);
spine.position.y = 0.25;
spine.castShadow = true;
torsoGroup.add(spine);

const chestGroup = new THREE.Group();
chestGroup.position.y = 0.5;
torsoGroup.add(chestGroup);

const chest = new THREE.Mesh(
  new THREE.CylinderGeometry(0.22, 0.16, 0.45, 16),
  giMat
);
chest.position.y = 0.225;
chest.castShadow = true;
chestGroup.add(chest);

const belt = new THREE.Mesh(
  new THREE.TorusGeometry(0.19, 0.04, 8, 32),
  beltMat
);
belt.rotation.x = Math.PI / 2;
belt.position.y = 0.02;
chestGroup.add(belt);

const neck = new THREE.Mesh(
  new THREE.CylinderGeometry(0.08, 0.1, 0.15, 12),
  skinMat
);
neck.position.y = 0.52;
chestGroup.add(neck);

const headGroup = new THREE.Group();
headGroup.position.y = 0.6;
chestGroup.add(headGroup);

const head = new THREE.Mesh(
  new THREE.SphereGeometry(0.14, 24, 24),
  skinMat
);
head.castShadow = true;
headGroup.add(head);

const hair = new THREE.Mesh(
  new THREE.SphereGeometry(0.15, 24, 24, 0, Math.PI * 2, 0, Math.PI / 2.5),
