function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  const breath = Math.sin(t * 2) * 0.03;
  chestGroup.scale.set(1 + breath * 0.2, 1 + breath, 1 + breath * 0.3);

  const stancePhase = (t * 0.8) % (Math.PI * 2);
  const combatCycle = Math.sin(stancePhase);

  hips.position.y = 0.8 + Math.abs(Math.sin(t * 3)) * 0.03;
  hips.rotation.y = Math.sin(stancePhase * 0.5) * 0.3;

  if (combatCycle > 0) {
    leftLeg.hip.rotation.x = -0.4 + Math.sin(t * 4) * 0.1;
    leftLeg.knee.rotation.x = 0.8 + Math.sin(t * 4) * 0.1;
    rightLeg.hip.rotation.x = 0.2;
    rightLeg.knee.rotation.x = 0.1;

    leftArm.shoulder.rotation.z = Math.PI / 3 + Math.sin(t * 6) * 0.2;
    leftArm.shoulder.rotation.x = -0.5;
    leftArm.elbow.rotation.x = -1.2 + Math.sin(t * 6) * 0.3;

    rightArm.shoulder.rotation.z = -Math.PI / 4;
    rightArm.shoulder.rotation.x = -0.8 + Math.sin(t * 6 + Math.PI) * 0.4;
    rightArm.elbow.rotation.x = -0.5;
  } else {
    leftLeg.hip.rotation.x = 0.2;
    leftLeg.knee.rotation.x = 0.1;
    rightLeg.hip.rotation.x = -0.4 + Math.sin(t * 4 + Math.PI) * 0.1;
    rightLeg.knee.rotation.x = 0.8 + Math.sin(t * 4 + Math.PI) * 0.1;

    rightArm.shoulder.rotation.z = -Math.PI / 3 - Math.sin(t * 6) * 0.2;
    rightArm.shoulder.rotation.x = -0.5;
    rightArm.elbow.rotation.x = -1.2 + Math.sin(t * 6) * 0.3;

    leftArm.shoulder.rotation.z = Math.PI / 4;
    leftArm.shoulder.rotation.x = -0.8 + Math.sin(t * 6 + Math.PI) * 0.4;
    leftArm.elbow.rotation.x = -0.5;
  }

  headGroup.rotation.y = Math.sin(stancePhase * 0.3) * 0.2;
  headGroup.rotation.x = Math.sin(t * 2) * 0.05;

  ponytail.rotation.x = -Math.PI / 3 + Math.sin(t * 8) * 0.1 + Math.cos(t * 12) * 0.05;

  dustSystem.rotation.y = t * 0.05;
  const positions = dustSystem.geometry.attributes.position.array;
  for(let i = 1; i < positions.length; i += 3) {
    positions[i] += Math.sin(t + positions[i-1]) * 0.002;
    if (positions[i] > 8) positions[i] = -1;
  }
  dustSystem.geometry.attributes.position.needsUpdate = true;

  rimLight.intensity = 0.75 + Math.sin(t * 0.8) * 0.15;

  controls.update();
  renderer.render(scene, camera);
}

