let punchPhase = 0;
let punchTimer = 0;
const punchCycle = 3.5;

function triggerExplosion(position) {
  explosionGroup.position.copy(position);
  explosionLight.intensity = 8;

  shockwave.scale.set(0.1, 0.1, 0.1);
  shockwaveMat.opacity = 0.8;

  explosionCore.scale.set(0.1, 0.1, 0.1);
  coreMat.opacity = 0.9;

  const colors = [0xffff00, 0xff8800, 0xff4400, 0xffaa00];
  for(let i = 0; i < particleCount; i++) {
    const angle = Math.random() * Math.PI * 2;
    const elevation = (Math.random() - 0.5) * Math.PI;
    const speed = 2 + Math.random() * 4;

    particleData[i].velocity.set(
      Math.cos(angle) * Math.cos(elevation) * speed,
      Math.sin(elevation) * speed,
      Math.sin(angle) * Math.cos(elevation) * speed
    );
    particleData[i].life = 1.0;
    particleData[i].active = true;
    particleData[i].rotationSpeed.set(
      Math.random() - 0.5,
      Math.random() - 0.5,
      Math.random() - 0.5
    ).multiplyScalar(0.2);

    dummy.position.set(0, 0, 0);
    dummy.rotation.set(0, 0, 0);
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    debrisMesh.setMatrixAt(i, dummy.matrix);
    debrisMesh.setColorAt(i, new THREE.Color(colors[Math.floor(Math.random() * colors.length)]));
  }
  debrisMesh.instanceMatrix.needsUpdate = true;
  if(debrisMesh.instanceColor) debrisMesh.instanceColor.needsUpdate = true;
  particleMat.opacity = 1;

  const sparkPos = sparks.geometry.attributes.position.array;
  for(let i = 0; i < sparkCount; i++) {
    sparkPos[i * 3] = 0;
    sparkPos[i * 3 + 1] = 0;
    sparkPos[i * 3 + 2] = 0;
    const angle = Math.random() * Math.PI * 2;
    const speed = 3 + Math.random() * 5;
    sparkVelocities[i].set(
      Math.cos(angle) * speed,
      (Math.random() - 0.5) * speed,
      Math.sin(angle) * speed
    );
  }
  sparkMat.opacity = 1;
  sparks.geometry.attributes.position.needsUpdate = true;

  renderer.toneMappingExposure = 2.5;
  setTimeout(() => { renderer.toneMappingExposure = 1.08; }, 100);
}

function updateExplosion(delta) {
  explosionLight.intensity = THREE.MathUtils.lerp(explosionLight.intensity, 0, delta * 4);

  shockwave.scale.multiplyScalar(1 + delta * 8);
  shockwaveMat.opacity = Math.max(0, shockwaveMat.opacity - delta * 1.5);

  explosionCore.scale.multiplyScalar(1 + delta * 3);
  coreMat.opacity = Math.max(0, coreMat.opacity - delta * 1.2);

  let activeParticles = 0;
  for(let i = 0; i < particleCount; i++) {
    if(particleData[i].active) {
      particleData[i].life -= delta * 0.8;

      dummy.position.copy(particleData[i].velocity).multiplyScalar(punchTimer * 0.3);
      dummy.position.multiplyScalar(1 - particleData[i].life * 0.5);
      dummy.rotation.x += particleData[i].rotationSpeed.x;
      dummy.rotation.y += particleData[i].rotationSpeed.y;
      dummy.scale.setScalar(particleData[i].life);
      dummy.updateMatrix();
      debrisMesh.setMatrixAt(i, dummy.matrix);

      if(particleData[i].life <= 0) {
        particleData[i].active = false;
        dummy.scale.set(0, 0, 0);
        dummy.updateMatrix();
        debrisMesh.setMatrixAt(i, dummy.matrix);
      } else {
        activeParticles++;
      }
    }
  }
  if(activeParticles > 0) {
    debrisMesh.instanceMatrix.needsUpdate = true;
    particleMat.opacity = Math.max(0, particleMat.opacity - delta * 0.8);
  }

  const sparkPos = sparks.geometry.attributes.position.array;
  for(let i = 0; i < sparkCount; i++) {
    sparkPos[i * 3] += sparkVelocities[i].x * delta;
    sparkPos[i * 3 + 1] += sparkVelocities[i].y * delta;
    sparkPos[i * 3 + 2] += sparkVelocities[i].z * delta;
    sparkVelocities[i].multiplyScalar(0.95);
  }
  sparkMat.opacity = Math.max(0, sparkMat.opacity - delta * 2);
  sparks.geometry.attributes.position.needsUpdate = true;
}

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  punchTimer += delta;
  if(punchTimer > punchCycle) {
    punchTimer = 0;
    punchPhase = 0;
  }

  const normalizedTime = punchTimer / punchCycle;

  if(normalizedTime < 0.3) {
    punchPhase = 0;
    const windUp = normalizedTime / 0.3;

    hips.rotation.y = THREE.MathUtils.lerp(0, -0.6, windUp);
    chestGroup.rotation.y = THREE.MathUtils.lerp(0, -0.4, windUp);

    rightArm.shoulder.rotation.z = THREE.MathUtils.lerp(0, Math.PI / 2, windUp);
    rightArm.shoulder.rotation.x = THREE.MathUtils.lerp(0, -0.5, windUp);
    rightArm.elbow.rotation.x = THREE.MathUtils.lerp(0, -2.0, windUp);

    leftArm.shoulder.rotation.z = THREE.MathUtils.lerp(0, Math.PI / 4, windUp);
    leftArm.shoulder.rotation.x = THREE.MathUtils.lerp(0, 0.3, windUp);

    rightLeg.hip.rotation.x = THREE.MathUtils.lerp(0, -0.3, windUp);
    leftLeg.hip.rotation.x = THREE.MathUtils.lerp(0, 0.3, windUp);

  } else if(normalizedTime < 0.38) {
    punchPhase = 1;
    const punchProgress = (normalizedTime - 0.3) / 0.08;

    hips.rotation.y = THREE.MathUtils.lerp(-0.6, 0.8, punchProgress);
    chestGroup.rotation.y = THREE.MathUtils.lerp(-0.4, 0.6, punchProgress);

    rightArm.shoulder.rotation.z = THREE.MathUtils.lerp(Math.PI / 2, 0, punchProgress);
    rightArm.shoulder.rotation.x = THREE.MathUtils.lerp(-0.5, -1.2, punchProgress);
    rightArm.elbow.rotation.x = THREE.MathUtils.lerp(-2.0, -0.1, punchProgress);

    const handPos = new THREE.Vector3();
    rightArm.hand.getWorldPosition(handPos);

  } else if(normalizedTime < 0.4) {
    if(punchPhase !== 2) {
      punchPhase = 2;
      const handPos = new THREE.Vector3();
      rightArm.hand.getWorldPosition(handPos);
      const forward = new THREE.Vector3(0, 0, 1).applyQuaternion(character.quaternion);
      handPos.add(forward.multiplyScalar(0.5));
      triggerExplosion(handPos);

      camera.position.x += (Math.random() - 0.5) * 0.2;
      camera.position.y += (Math.random() - 0.5) * 0.2;
    }
  } else {
    punchPhase = 3;
    const recover = (normalizedTime - 0.4) / 0.6;
    const breathe = Math.sin(t * 3) * 0.03;

    hips.rotation.y = THREE.MathUtils.lerp(0.8, Math.sin(t * 0.5) * 0.2, recover);
    chestGroup.rotation.y = THREE.MathUtils.lerp(0.6, 0, recover);

    rightArm.shoulder.rotation.z = THREE.MathUtils.lerp(0, Math.sin(t * 2) * 0.1, recover);
    rightArm.shoulder.rotation.x = THREE.MathUtils.lerp(-1.2, -0.2 + breathe, recover);
    rightArm.elbow.rotation.x = THREE.MathUtils.lerp(-0.1, -0.5, recover);

    leftArm.shoulder.rotation.z = Math.PI / 6 + Math.sin(t * 2 + Math.PI) * 0.1;

    rightLeg.hip.rotation.x = THREE.MathUtils.lerp(-0.3, 0.1, recover);
    leftLeg.hip.rotation.x = THREE.MathUtils.lerp(0.3, -0.1, recover);
  }

  const breath = Math.sin(t * 2) * 0.03;
  chestGroup.scale.set(1 + breath * 0.2, 1 + breath, 1 + breath * 0.3);
  hips.position.y = 0.8 + Math.abs(Math.sin(t * 3)) * 0.03;

  headGroup.rotation.y = Math.sin(t * 0.5) * 0.1;
  headGroup.rotation.x = Math.sin(t * 2) * 0.05;
  ponytail.rotation.x = -Math.PI / 3 + Math.sin(t * 8) * 0.1;

  dustSystem.rotation.y = t * 0.05;
  const positions = dustSystem.geometry.attributes.position.array;
  for(let i = 1; i < positions.length; i += 3) {
    positions[i] += Math.sin(t + positions[i-1]) * 0.002;
    if (positions[i] > 8) positions[i] = -1;
  }
  dustSystem.geometry.attributes.position.needsUpdate = true;

  rimLight.intensity = 0.75 + Math.sin(t * 0.8) * 0.15;

  updateExplosion(delta);

  controls.update();
  renderer.render(scene, camera);
}

